#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Page { Collection, Lookup, Queue }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Overlay { None, Help, Filter }

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FocusRing { len: usize, index: usize }

impl FocusRing {
    pub fn new(len: usize) -> Self { Self { len, index: 0 } }
    pub fn index(&self) -> usize { self.index }
    pub fn next(&mut self) {
        if self.len > 0 { self.index = (self.index + 1) % self.len; }
    }
    pub fn previous(&mut self) {
        if self.len > 0 { self.index = (self.index + self.len - 1) % self.len; }
    }
    pub fn set_len(&mut self, len: usize) {
        self.len = len;
        self.index = if len == 0 { 0 } else { self.index.min(len - 1) };
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UiState { pub page: Page, pub overlay: Overlay, pub focus: FocusRing }

impl UiState {
    pub fn new(focusable: usize) -> Self { Self { page: Page::Collection, overlay: Overlay::None, focus: FocusRing::new(focusable) } }
    pub fn navigate(&mut self, page: Page) { self.page = page; }
    pub fn close_overlay(&mut self) { self.overlay = Overlay::None; }
}
